      schedule();

      return () => {
        disposed = true;
        cancelAnimationFrame(frame);
        cancelAnimationFrame(resizeFrame);
        resizeObserver.disconnect();
        wrapper.removeEventListener('pointerdown', onPointerDown);
        window.removeEventListener('pointerup', onPointerUp);
