p='src/CpuLoadChart/CpuLoadChart.tsx'
s=open(p).read()
s=s.replace("import type uPlot from 'uplot';\n","")
s=s.replace("const SERIES_ID = 'cpu';","type UPlot = Yagr['uplot'];\n\nconst SERIES_ID = 'cpu';")
s=s.replace("(u: uPlot","(u: UPlot")
open(p,'w').write(s)
p='src/CpuLoadChart/model.ts'
s=open(p).read()
s=s.replace("""/**
