grep -n "uPlot\|UPlot" src/CpuLoadChart/CpuLoadChart.tsx
cat > src/CpuLoadChart/CpuLoadChart.css <<'EOF'
.cpu-load-chart {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

